package com.gamemargins;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import lombok.Data;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * gamemargins.com's RuneLite API, through RuneLite's OkHttp client, always asynchronous (enqueue): nothing
 * here runs on the client thread, and callbacks come back on OkHttp's pool (callers hop to the client thread
 * or Swing themselves). The site's routes: POST /api/runelite/link (start linking), POST /api/runelite/link/poll,
 * POST /api/runelite/offers (a batch of events, with the token), GET /api/runelite/status, GET /api/runelite/limits.
 */
@Slf4j
public class ApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	/** What a request came back with: the HTTP status and the JSON body (null when it wasn't JSON). */
	@Data
	public static class Reply
	{
		private final int status;
		private final JsonObject body;
		/** Set when the request never reached the server. */
		private final IOException failure;

		public boolean ok()
		{
			return failure == null && status >= 200 && status < 300;
		}
	}

	/** A batch of events as the site takes it. */
	@Data
	public static class Batch
	{
		private final int tzOffset;
		private final List<OfferEvent> events;
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final String site;

	public ApiClient(OkHttpClient http, Gson gson, String site)
	{
		this.http = http;
		this.gson = gson;
		this.site = site.endsWith("/") ? site.substring(0, site.length() - 1) : site;
	}

	public String getSite()
	{
		return site;
	}

	private HttpUrl url(String path)
	{
		HttpUrl base = HttpUrl.parse(site + path);
		if (base == null)
		{
			throw new IllegalArgumentException("not a URL: " + site + path);
		}
		return base;
	}

	public void startLink(Consumer<Reply> done)
	{
		send(new Request.Builder().url(url("/api/runelite/link")).post(RequestBody.create(JSON, "{}")).build(), done);
	}

	public void pollLink(String deviceCode, Consumer<Reply> done)
	{
		JsonObject body = new JsonObject();
		body.addProperty("deviceCode", deviceCode);
		send(new Request.Builder().url(url("/api/runelite/link/poll")).post(RequestBody.create(JSON, gson.toJson(body))).build(), done);
	}

	public void sendOffers(String token, int tzOffset, List<OfferEvent> events, Consumer<Reply> done)
	{
		String json = gson.toJson(new Batch(tzOffset, events));
		send(new Request.Builder().url(url("/api/runelite/offers")).header("Authorization", "Bearer " + token).post(RequestBody.create(JSON, json)).build(), done);
	}

	public void status(String token, Consumer<Reply> done)
	{
		send(new Request.Builder().url(url("/api/runelite/status")).header("Authorization", "Bearer " + token).get().build(), done);
	}

	public void limits(Consumer<Reply> done)
	{
		send(new Request.Builder().url(url("/api/runelite/limits")).get().build(), done);
	}

	/** The buy limits in a /api/runelite/limits reply: item id → limit. */
	public Map<Integer, Integer> readLimits(JsonObject body)
	{
		Map<Integer, Integer> out = new java.util.HashMap<>();
		if (body == null || !body.has("limits"))
		{
			return out;
		}
		for (Map.Entry<String, com.google.gson.JsonElement> e : body.getAsJsonObject("limits").entrySet())
		{
			try
			{
				out.put(Integer.parseInt(e.getKey()), e.getValue().getAsInt());
			}
			catch (NumberFormatException | IllegalStateException ignored)
			{
				// Not an item id or not a number: left out.
			}
		}
		return out;
	}

	private void send(Request request, Consumer<Reply> done)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				done.accept(new Reply(0, null, e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					JsonObject body = null;
					String text = r.body() == null ? "" : r.body().string();
					if (!text.isEmpty())
					{
						try
						{
							body = gson.fromJson(text, JsonObject.class);
						}
						catch (JsonSyntaxException e)
						{
							log.debug("not JSON from {}: {}", request.url(), text.length() > 200 ? text.substring(0, 200) : text);
						}
					}
					done.accept(new Reply(r.code(), body, null));
				}
				catch (IOException e)
				{
					done.accept(new Reply(0, null, e));
				}
			}
		});
	}
}

package com.gamemargins;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntFunction;
import lombok.AllArgsConstructor;
import lombok.Data;

/**
 * The Grand Exchange's buy limits run in 4-hour windows: the window starts with the first item bought and
 * ends 4 hours later, whatever came after; then the whole limit is free again. The same rule as the site's
 * core buyLimitWindow, so the panel, the overlay and gamemargins.com agree.
 */
public final class BuyLimits
{
	public static final long WINDOW_MS = 4L * 60 * 60 * 1000;
	/** Purchases older than this can't be in a window that is still open. */
	public static final long LOOKBACK_MS = 24L * 60 * 60 * 1000;

	private BuyLimits()
	{
	}

	/** One item's open window. */
	@Data
	@AllArgsConstructor
	public static class Window
	{
		private final int itemId;
		/** When the window started: the first purchase in it (ms). */
		private final long start;
		/** When the limit frees up again (ms). */
		private final long resets;
		/** Items bought in the window. */
		private final int used;
		/** The item's limit, or -1 when unknown. */
		private final int limit;

		/** How many may still be bought; -1 when the limit is unknown. */
		public int getLeft()
		{
			return limit < 0 ? -1 : Math.max(0, limit - used);
		}
	}

	/**
	 * The window open at {@code now} for one item, or null when the last window has ended. Purchases are
	 * walked oldest first; one that falls after the running window's end starts a new one. A purchase timed
	 * after now (a clock that was ahead) counts as now.
	 */
	public static Window window(int itemId, List<Purchase> purchases, long now, int limit)
	{
		List<Purchase> sorted = new ArrayList<>();
		for (Purchase p : purchases)
		{
			if (p.getItemId() == itemId && p.getQuantity() > 0)
			{
				sorted.add(new Purchase(itemId, p.getQuantity(), Math.min(p.getAt(), now)));
			}
		}
		sorted.sort(Comparator.comparingLong(Purchase::getAt));
		long start = -1;
		int used = 0;
		for (Purchase p : sorted)
		{
			if (start < 0 || p.getAt() >= start + WINDOW_MS)
			{
				start = p.getAt();
				used = 0;
			}
			used += p.getQuantity();
		}
		if (start < 0 || now >= start + WINDOW_MS)
		{
			return null;
		}
		return new Window(itemId, start, start + WINDOW_MS, used, limit);
	}

	/** The open windows of every item with purchases, soonest reset first. {@code limitOf} gives an item's limit, or null when unknown. */
	public static List<Window> windows(List<Purchase> purchases, long now, IntFunction<Integer> limitOf)
	{
		Set<Integer> items = new LinkedHashSet<>();
		for (Purchase p : purchases)
		{
			items.add(p.getItemId());
		}
		List<Window> out = new ArrayList<>();
		for (int itemId : items)
		{
			Integer limit = limitOf.apply(itemId);
			Window w = window(itemId, purchases, now, limit == null ? -1 : limit);
			if (w != null)
			{
				out.add(w);
			}
		}
		out.sort(Comparator.comparingLong(Window::getResets));
		return out;
	}

	/** "2h 05m", "45 min", "under a minute". */
	public static String until(long ms)
	{
		if (ms < 60_000)
		{
			return "under a minute";
		}
		long minutes = (ms + 59_999) / 60_000;
		if (minutes < 60)
		{
			return minutes + " min";
		}
		return String.format("%dh %02dm", minutes / 60, minutes % 60);
	}
}

package com.gamemargins;

import java.util.ArrayList;
import java.util.List;

/**
 * The events waiting to go to gamemargins.com, in order, persisted by the Store so nothing is lost when
 * RuneLite closes or the site is down. Sent in batches with a backoff that doubles on failure (5 s up to
 * 5 minutes). Bounded: past {@link #MAX} the oldest events are dropped, which the site tolerates (an offer
 * whose earlier events are missing is taken from its latest state).
 */
public class EventQueue
{
	public static final int MAX = 5_000;
	/** Events per batch; the site accepts up to 500. */
	public static final int BATCH = 200;
	public static final long FIRST_BACKOFF_MS = 5_000;
	public static final long MAX_BACKOFF_MS = 5 * 60_000;

	private final List<OfferEvent> events = new ArrayList<>();
	private long backoffMs = 0;
	private long notBefore = 0;
	private boolean inFlight;

	public synchronized void addAll(List<OfferEvent> fresh)
	{
		events.addAll(fresh);
		while (events.size() > MAX)
		{
			events.remove(0);
		}
	}

	/** Puts the events of the last session in front of whatever arrived since the plugin started. */
	public synchronized void restore(List<OfferEvent> saved)
	{
		events.addAll(0, saved);
		while (events.size() > MAX)
		{
			events.remove(0);
		}
	}

	public synchronized void clear()
	{
		events.clear();
		inFlight = false;
		backoffMs = 0;
		notBefore = 0;
	}

	public synchronized List<OfferEvent> snapshot()
	{
		return new ArrayList<>(events);
	}

	public synchronized int size()
	{
		return events.size();
	}

	public synchronized boolean isEmpty()
	{
		return events.isEmpty();
	}

	/** The next batch to send, or null when nothing is due (empty, a send in flight, or backing off). */
	public synchronized List<OfferEvent> take(long now)
	{
		if (inFlight || events.isEmpty() || now < notBefore)
		{
			return null;
		}
		inFlight = true;
		return new ArrayList<>(events.subList(0, Math.min(BATCH, events.size())));
	}

	/** The batch was accepted: drop it and send again at once. */
	public synchronized void sent(List<OfferEvent> batch)
	{
		events.removeAll(batch);
		inFlight = false;
		backoffMs = 0;
		notBefore = 0;
	}

	/** The batch was refused as malformed: it would never be accepted, so it goes. */
	public synchronized void dropped(List<OfferEvent> batch)
	{
		sent(batch);
	}

	/** The batch could not be delivered: keep it, wait longer each time. */
	public synchronized void failed(long now)
	{
		inFlight = false;
		backoffMs = backoffMs == 0 ? FIRST_BACKOFF_MS : Math.min(MAX_BACKOFF_MS, backoffMs * 2);
		notBefore = now + backoffMs;
	}

	public synchronized long getBackoffMs()
	{
		return backoffMs;
	}
}

package com.gamemargins;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;

@ConfigGroup(GameMarginsConfig.GROUP)
public interface GameMarginsConfig extends Config
{
	String GROUP = "gamemargins";
	/** The token the device flow gave this installation; set and cleared by the plugin, never typed. */
	String TOKEN_KEY = "token";

	@ConfigSection(
		name = "Notifications",
		description = "What the plugin tells you in the game",
		position = 10
	)
	String NOTIFICATIONS = "notifications";

	@ConfigItem(
		keyName = "siteUrl",
		name = "Site",
		description = "Where the plugin sends your Grand Exchange offers once you have linked it on the site: gamemargins.com. Change it only to test against a copy of the site.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 1
	)
	default String siteUrl()
	{
		return "https://gamemargins.com";
	}

	@ConfigItem(
		keyName = "overlay",
		name = "Buy limit in the offer screen",
		description = "When you set up a buy offer, show how much of the item's buy limit you have left and when it resets",
		position = 2
	)
	default boolean overlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyLimitReset",
		name = "Buy limit reset",
		description = "Tell me when a buy limit of an item I bought frees up again",
		section = NOTIFICATIONS,
		position = 11
	)
	default Notification notifyLimitReset()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "notifyOfferDone",
		name = "Offer finished",
		description = "Tell me when a buy or sell offer has fully filled",
		section = NOTIFICATIONS,
		position = 12
	)
	default Notification notifyOfferDone()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = TOKEN_KEY,
		name = "",
		description = "",
		hidden = true,
		secret = true
	)
	default String token()
	{
		return "";
	}
}

package com.gamemargins;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.text.NumberFormat;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.ProgressBar;

/**
 * The side panel (decision 3B/3C): link status with the code while linking, the account and today's profit
 * (from the site), the eight slots with their progress, the buy limits with their countdowns, and when the
 * site last took a batch. Rebuilt from a snapshot the plugin hands it ({@link #show}); everything here runs
 * on the Swing thread. Every line of text is in Geist, the site's letter ({@link PanelFonts}).
 */
public class GameMarginsPanel extends PluginPanel
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.systemDefault());
	private static final Color GREEN = new Color(55, 240, 70);
	private static final Color AMBER = new Color(230, 150, 30);
	private static final Color DIM = new Color(143, 143, 143);
	/**
	 * Where text wraps, in CSS pixels: Swing's HTML counts a CSS pixel as 1.3 screen pixels, so this keeps the
	 * text 40 pixels inside the panel (a CSS width of PANEL_WIDTH - 40 ran past the edge and was cut off).
	 */
	private static final int WRAP_WIDTH = Math.round((PANEL_WIDTH - 40) / 1.3f);

	/** What the panel shows, taken off the plugin's state on the client thread. */
	public static class View
	{
		public boolean linked;
		public LinkFlow.State linkState = LinkFlow.State.IDLE;
		public String userCode;
		public String linkProblem;
		public String accountName;
		public boolean worldTracked = true;
		public boolean loggedIn;
		public Long todayProfit;
		public Integer todayTrades;
		public SlotState[] slots = new SlotState[OfferTracker.SLOTS];
		public List<BuyLimits.Window> windows = java.util.Collections.emptyList();
		public java.util.function.IntFunction<String> nameOf = id -> "Item " + id;
		public long lastSyncAt;
		public int queued;
		public String syncProblem;
	}

	private final Runnable onLink;
	private final Runnable onOpenPage;
	private final Runnable onUnlink;
	private final JPanel body = new JPanel();

	public GameMarginsPanel(Runnable onLink, Runnable onOpenPage, Runnable onUnlink)
	{
		// Wrapped in RuneLite's scroll pane (the default), so a long list of slots and limits scrolls.
		super();
		this.onLink = onLink;
		this.onOpenPage = onOpenPage;
		this.onUnlink = onUnlink;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		body.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		add(body, BorderLayout.NORTH);
	}

	/** Shows a view; safe to call from any thread. */
	public void show(View view)
	{
		SwingUtilities.invokeLater(() -> rebuild(view));
	}

	private void rebuild(View v)
	{
		body.removeAll();
		NumberFormat n = NumberFormat.getIntegerInstance();

		body.add(label("GameMargins", PanelFonts.TITLE, Color.WHITE));
		body.add(Box.createVerticalStrut(8));

		if (!v.linked)
		{
			body.add(text("Link this plugin to your gamemargins.com account: your Grand Exchange offers then fill your trades and buy-limit timers on the site by themselves.", DIM));
			body.add(Box.createVerticalStrut(8));
			if (v.linkState == LinkFlow.State.WAITING && v.userCode != null)
			{
				body.add(text("On gamemargins.com/link, confirm this code:", Color.WHITE));
				body.add(label(v.userCode, PanelFonts.CODE, Color.WHITE));
				body.add(text("Waiting for you to confirm…", DIM));
				body.add(Box.createVerticalStrut(6));
				body.add(button("Open the page again", onOpenPage));
			}
			else
			{
				if (v.linkState == LinkFlow.State.FAILED && v.linkProblem != null)
				{
					body.add(text(v.linkProblem, AMBER));
					body.add(Box.createVerticalStrut(6));
				}
				body.add(button(v.linkState == LinkFlow.State.STARTING ? "Asking for a code…" : "Link", onLink));
			}
			body.add(Box.createVerticalStrut(8));
			body.add(text("Nothing is sent before you link. What is sent then: your offers (item, quantity, price, what filled and when), your account's number and name.", DIM));
			body.revalidate();
			body.repaint();
			return;
		}

		if (!v.loggedIn)
		{
			body.add(text("Log in to see your slots.", DIM));
		}
		else if (!v.worldTracked)
		{
			body.add(text("This world has its own economy (Leagues, Deadman, beta…): offers here are not tracked.", AMBER));
		}
		else
		{
			JPanel head = new JPanel(new BorderLayout(6, 0));
			head.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			head.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 8));
			head.setAlignmentX(LEFT_ALIGNMENT);
			head.add(label(v.accountName == null ? "Account" : v.accountName, PanelFonts.BODY, Color.WHITE), BorderLayout.CENTER);
			if (v.todayProfit != null)
			{
				long profit = v.todayProfit;
				JLabel today = label((profit > 0 ? "+" : "") + n.format(profit) + " today", PanelFonts.BODY, profit > 0 ? GREEN : profit < 0 ? Color.RED : DIM);
				today.setToolTipText(v.todayTrades == null ? null : v.todayTrades + " trades sold today, profit after tax");
				head.add(today, BorderLayout.EAST);
			}
			body.add(head);
			body.add(Box.createVerticalStrut(8));

			body.add(section("Offers"));
			int empty = 0;
			for (int i = 0; i < v.slots.length; i++)
			{
				SlotState s = v.slots[i];
				if (s == null || s.isEmpty())
				{
					empty++;
					continue;
				}
				body.add(slotRow(s, v.nameOf.apply(s.getItemId()), n));
				body.add(Box.createVerticalStrut(4));
			}
			if (empty > 0)
			{
				body.add(text(empty + (empty == 1 ? " empty slot" : " empty slots"), DIM));
			}
			body.add(Box.createVerticalStrut(8));

			body.add(section("Buy limits"));
			if (v.windows.isEmpty())
			{
				body.add(text("Nothing bought in the last 4 hours", DIM));
			}
			long now = System.currentTimeMillis();
			for (BuyLimits.Window w : v.windows)
			{
				JPanel row = new JPanel(new BorderLayout(6, 0));
				row.setBackground(ColorScheme.DARK_GRAY_COLOR);
				row.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR));
				row.setAlignmentX(LEFT_ALIGNMENT);
				row.add(label(v.nameOf.apply(w.getItemId()), PanelFonts.BODY, Color.WHITE), BorderLayout.CENTER);
				String left = w.getLeft() < 0 ? n.format(w.getUsed()) + " bought" : w.getLeft() == 0 ? "full" : n.format(w.getLeft()) + " left";
				JLabel when = label(left + " · " + CLOCK.format(Instant.ofEpochMilli(w.getResets())), PanelFonts.BODY, w.getLeft() == 0 ? AMBER : DIM);
				when.setToolTipText("Frees up in " + BuyLimits.until(w.getResets() - now));
				row.add(when, BorderLayout.EAST);
				body.add(row);
			}
		}

		body.add(Box.createVerticalStrut(10));
		String sync;
		if (v.syncProblem != null)
		{
			sync = v.syncProblem;
		}
		else if (v.lastSyncAt == 0)
		{
			// Nothing sent since RuneLite started, and nothing waiting: the site has all there is. ("Nothing sent
			// yet" read as if the link didn't work, while today's profit above had just come from the site.)
			sync = v.queued > 0 ? v.queued + " to send" : "Up to date";
		}
		else
		{
			long ago = Math.max(0, now() - v.lastSyncAt);
			sync = "Synced " + (ago < 60_000 ? (ago / 1000) + " s ago" : BuyLimits.until(ago) + " ago") + (v.queued > 0 ? " · " + v.queued + " to send" : "");
		}
		body.add(text(sync, v.syncProblem != null ? AMBER : DIM));
		body.add(Box.createVerticalStrut(6));
		body.add(button("Unlink", onUnlink));
		body.revalidate();
		body.repaint();
	}

	private static long now()
	{
		return System.currentTimeMillis();
	}

	private JPanel slotRow(SlotState s, String name, NumberFormat n)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 8));
		row.setAlignmentX(LEFT_ALIGNMENT);
		// Everything in the row lines up on the left: BoxLayout puts a left-aligned label (the price) at the
		// middle of panels that are centred by default.
		JPanel line = new JPanel(new BorderLayout(6, 0));
		line.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		line.setAlignmentX(LEFT_ALIGNMENT);
		// The name takes what the numbers leave, and is shortened with "…" when it doesn't fit.
		line.add(label(name, PanelFonts.BODY, Color.WHITE), BorderLayout.CENTER);
		String state = s.isCancelled() ? "Cancelled" : s.isFinished() ? "Done" : s.isBuy() ? "Buy" : "Sell";
		Color stateColor = s.isCancelled() ? Color.RED : s.isFinished() ? GREEN : DIM;
		line.add(label(state + " " + n.format(s.getFilled()) + " / " + n.format(s.getQuantity()), PanelFonts.BODY, stateColor), BorderLayout.EAST);
		row.add(line);
		ProgressBar bar = new ProgressBar();
		bar.setMaximumValue(Math.max(1, s.getQuantity()));
		bar.setValue(s.getFilled());
		bar.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		bar.setForeground(s.isFinished() && !s.isCancelled() ? GREEN : AMBER);
		bar.setPreferredSize(new Dimension(PANEL_WIDTH - 40, 6));
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 6));
		bar.setAlignmentX(LEFT_ALIGNMENT);
		row.add(Box.createVerticalStrut(3));
		row.add(bar);
		row.add(label(n.format(s.getPrice()) + " each", PanelFonts.SMALL, DIM));
		return row;
	}

	/** A line of text in one of the panel's letters ({@link PanelFonts}), lined up on the left. */
	private static JLabel label(String s, Font font, Color color)
	{
		JLabel label = PanelFonts.use(new JLabel(s), font);
		label.setForeground(color);
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	private static JLabel section(String name)
	{
		return label(name.toUpperCase(), PanelFonts.SECTION, ColorScheme.BRAND_ORANGE);
	}

	private static JLabel text(String s, Color color)
	{
		return label("<html><div style='width:" + WRAP_WIDTH + "px'>" + escape(s) + "</div></html>", PanelFonts.SMALL, color);
	}

	private static JButton button(String label, Runnable action)
	{
		JButton b = PanelFonts.use(new JButton(label), PanelFonts.BUTTON);
		b.setAlignmentX(LEFT_ALIGNMENT);
		b.addActionListener(e -> action.run());
		return b;
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.gamemargins;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TimeZone;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import okhttp3.OkHttpClient;

/**
 * GameMargins: Grand Exchange buy-limit timers and flip tracking, synced with gamemargins.com.
 *
 * <p>The plugin watches the eight Grand Exchange slots (GrandExchangeOfferChanged) and turns every change
 * into an event for the site (OfferTracker), queued on disk (EventQueue, Store) and sent in batches with a
 * bearer token the site handed out when the player linked the plugin (LinkFlow: a code shown here,
 * confirmed on gamemargins.com/link). Nothing is sent before that. The side panel (GameMarginsPanel) shows
 * the slots, the buy-limit windows (BuyLimits, from this plugin's own purchases) and today's profit from the
 * site; the overlay (GeOverlay) shows the limit left in the offer setup screen; the Notifier says when an
 * offer finishes or a limit frees up.
 *
 * <p>Threads: game events and the trackers live on the client thread; disk and network run on RuneLite's
 * executor and OkHttp's pool; the panel is rebuilt on Swing from a snapshot.
 */
@Slf4j
@PluginDescriptor(
	name = "GameMargins",
	description = "Grand Exchange buy-limit timers and flip tracking, synced with gamemargins.com",
	tags = {"flipping", "grand exchange", "ge", "buy limit", "timer", "merching", "profit"},
	internalName = "gamemargins"
)
public class GameMarginsPlugin extends Plugin
{
	/** Game ticks without an offer event after login before the slots are taken as settled. */
	private static final int REPLAY_QUIET_TICKS = 3;
	/** Ticks to wait for the account's file at most before settling without it. */
	private static final int REPLAY_MAX_TICKS = 50;
	private static final long FLUSH_EVERY_MS = 2_000;
	private static final long LIMITS_EVERY_HOURS = 24;
	private static final long STATUS_EVERY_MINUTES = 5;

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private OkHttpClient http;
	@Inject
	private Gson gson;
	@Inject
	private ConfigManager configManager;
	@Inject
	private GameMarginsConfig config;
	@Inject
	private Notifier notifier;
	@Inject
	private ClientToolbar toolbar;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private ItemManager itemManager;
	@Inject
	private ScheduledExecutorService executor;
	@Inject
	private GeOverlay overlay;

	private Store store;
	private ApiClient api;
	private LinkFlow link;
	private GameMarginsPanel panel;
	private NavigationButton navButton;
	private final EventQueue queue = new EventQueue();
	private final Map<String, OfferTracker> trackers = new HashMap<>();
	private final Map<Integer, String> itemNames = new HashMap<>();
	private final Map<String, Long> todayProfit = new HashMap<>();
	private final Map<String, Integer> todayTrades = new HashMap<>();
	private final Set<String> announcedResets = new HashSet<>();
	private volatile Map<Integer, Integer> limits = new HashMap<>();
	private OfferTracker current;
	private boolean worldTracked = true;
	private int quietTicks = -1;
	private int tick;
	private volatile long lastSyncAt;
	private volatile String syncProblem;
	private ScheduledFuture<?> flusher;
	private ScheduledFuture<?> limitsRefresh;
	private ScheduledFuture<?> statusRefresh;

	@Override
	protected void startUp() throws Exception
	{
		store = new Store(gson, getPluginDirectory());
		api = new ApiClient(http, gson, config.siteUrl());
		link = new LinkFlow(api, executor, this::linked, this::refreshPanel);
		panel = new GameMarginsPanel(() -> link.start(), () -> link.openPage(), this::unlink);
		navButton = NavigationButton.builder().tooltip("GameMargins").icon(icon()).priority(6).panel(panel).build();
		toolbar.addNavigation(navButton);
		overlayManager.add(overlay);
		// The queue from the last session, read off the executor so the client thread never waits on disk.
		executor.execute(() ->
		{
			List<OfferEvent> saved = store.loadQueue();
			if (!saved.isEmpty())
			{
				queue.restore(saved);
			}
			refreshPanel();
		});
		flusher = executor.scheduleWithFixedDelay(this::flush, FLUSH_EVERY_MS, FLUSH_EVERY_MS, TimeUnit.MILLISECONDS);
		if (isLinked())
		{
			limitsRefresh = executor.scheduleWithFixedDelay(this::fetchLimits, 0, LIMITS_EVERY_HOURS, TimeUnit.HOURS);
			statusRefresh = executor.scheduleWithFixedDelay(this::fetchStatus, 1, STATUS_EVERY_MINUTES * 60, TimeUnit.SECONDS);
		}
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::loggedIn);
		}
		refreshPanel();
		log.debug("GameMargins started");
	}

	@Override
	protected void shutDown()
	{
		if (flusher != null)
		{
			flusher.cancel(false);
		}
		if (limitsRefresh != null)
		{
			limitsRefresh.cancel(false);
		}
		if (statusRefresh != null)
		{
			statusRefresh.cancel(false);
		}
		link.cancel();
		toolbar.removeNavigation(navButton);
		overlayManager.remove(overlay);
		saveCurrent();
		trackers.clear();
		current = null;
		log.debug("GameMargins stopped");
	}

	@Provides
	GameMarginsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GameMarginsConfig.class);
	}

	// --- game events (client thread) ---------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				loggedIn();
				break;
			case LOGIN_SCREEN:
			case HOPPING:
			case CONNECTION_LOST:
				saveCurrent();
				if (event.getGameState() != GameState.HOPPING)
				{
					current = null;
				}
				refreshPanel();
				break;
			default:
				break;
		}
	}

	/** A login (or the plugin turned on while logged in): find the account's tracker and wait out the slot replay. */
	private void loggedIn()
	{
		long hash = client.getAccountHash();
		if (hash == -1)
		{
			return;
		}
		worldTracked = WorldFilter.tracked(client.getWorldType());
		String account = Long.toString(hash);
		current = trackers.computeIfAbsent(account, this::loadTracker);
		current.beginReplay();
		quietTicks = 0;
		refreshPanel();
	}

	private OfferTracker loadTracker(String account)
	{
		OfferTracker tracker = new OfferTracker(account, System::currentTimeMillis);
		// The account's file is read off the client thread; the login reconciliation waits until it is in.
		executor.execute(() ->
		{
			Store.AccountFile saved = store.loadAccount(account);
			clientThread.invoke(() ->
			{
				tracker.restore(saved == null ? null : saved.getSlots(), saved == null ? null : saved.getPurchases());
				if (saved != null && saved.getName() != null && tracker.getName() == null)
				{
					tracker.setName(saved.getName());
				}
			});
		});
		return tracker;
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (current == null)
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loggedIn();
			}
			if (current == null)
			{
				return;
			}
		}
		if (current.isReplaying())
		{
			// The login burst: the slots settle over a few ticks, the reconciliation reads them then.
			quietTicks = 0;
			return;
		}
		if (!worldTracked)
		{
			return;
		}
		noteName();
		List<OfferEvent> events = current.onChange(event.getSlot(), event.getOffer());
		if (events.isEmpty())
		{
			return;
		}
		GrandExchangeOffer offer = event.getOffer();
		if (offer.getState() == GrandExchangeOfferState.BOUGHT || offer.getState() == GrandExchangeOfferState.SOLD)
		{
			String what = offer.getState() == GrandExchangeOfferState.BOUGHT ? "Bought" : "Sold";
			notifier.notify(config.notifyOfferDone(), "GameMargins: " + what + " " + NumberFormat.getIntegerInstance().format(offer.getTotalQuantity()) + " " + nameOf(offer.getItemId()));
		}
		enqueue(events);
		saveCurrent();
		refreshPanel();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tick++;
		if (current != null && current.isReplaying())
		{
			quietTicks++;
			if (quietTicks >= REPLAY_QUIET_TICKS && (current.isRestored() || quietTicks >= REPLAY_MAX_TICKS))
			{
				settleReplay();
			}
			return;
		}
		if (current != null && tick % 5 == 0)
		{
			checkResets();
		}
		if (tick % 10 == 0)
		{
			refreshPanel();
		}
	}

	/** The client has settled after login: what changed while the plugin wasn't watching goes out, marked offline. */
	private void settleReplay()
	{
		noteName();
		List<OfferEvent> events = worldTracked ? current.endReplay(client.getGrandExchangeOffers()) : new ArrayList<>();
		if (!worldTracked)
		{
			current.endReplay(null);
		}
		if (!events.isEmpty())
		{
			enqueue(events);
			saveCurrent();
		}
		refreshPanel();
	}

	private void noteName()
	{
		Player me = client.getLocalPlayer();
		if (me != null && me.getName() != null && current != null)
		{
			current.setName(me.getName());
		}
	}

	/** A window that just ended: the whole limit is free again. Once per window. */
	private void checkResets()
	{
		long now = System.currentTimeMillis();
		List<Purchase> purchases = current.getPurchases();
		Set<Integer> items = new HashSet<>();
		for (Purchase p : purchases)
		{
			items.add(p.getItemId());
		}
		for (int itemId : items)
		{
			BuyLimits.Window open = BuyLimits.window(itemId, purchases, now, limitOf(itemId) == null ? -1 : limitOf(itemId));
			if (open != null)
			{
				continue;
			}
			// The last window ended: find when, and announce it if that was in the last minute.
			long lastAt = 0;
			for (Purchase p : purchases)
			{
				if (p.getItemId() == itemId)
				{
					lastAt = Math.max(lastAt, p.getAt());
				}
			}
			BuyLimits.Window last = BuyLimits.window(itemId, purchases, lastAt, -1);
			if (last == null || now - last.getResets() > 60_000)
			{
				continue;
			}
			String key = current.getAccount() + ":" + itemId + ":" + last.getResets();
			if (announcedResets.add(key))
			{
				Integer limit = limitOf(itemId);
				String again = limit == null ? "" : " You can buy " + NumberFormat.getIntegerInstance().format(limit) + " again.";
				notifier.notify(config.notifyLimitReset(), "GameMargins: buy limit reset for " + nameOf(itemId) + "." + again);
			}
		}
	}

	// --- the site -------------------------------------------------------------------------------------

	private boolean isLinked()
	{
		String token = config.token();
		return token != null && !token.isEmpty();
	}

	/** The device flow finished: keep the token, fetch the limits and the status, and start sending. */
	private void linked(String token)
	{
		configManager.setConfiguration(GameMarginsConfig.GROUP, GameMarginsConfig.TOKEN_KEY, token);
		syncProblem = null;
		if (limitsRefresh == null)
		{
			limitsRefresh = executor.scheduleWithFixedDelay(this::fetchLimits, 0, LIMITS_EVERY_HOURS, TimeUnit.HOURS);
		}
		if (statusRefresh == null)
		{
			statusRefresh = executor.scheduleWithFixedDelay(this::fetchStatus, 0, STATUS_EVERY_MINUTES * 60, TimeUnit.SECONDS);
		}
		refreshPanel();
	}

	/** The player unlinks here (or the site revoked the token): forget it, and the events waiting for it. */
	private void unlink()
	{
		configManager.unsetConfiguration(GameMarginsConfig.GROUP, GameMarginsConfig.TOKEN_KEY);
		link.cancel();
		queue.clear();
		executor.execute(() -> store.saveQueue(new ArrayList<>()));
		todayProfit.clear();
		todayTrades.clear();
		syncProblem = null;
		refreshPanel();
	}

	private void enqueue(List<OfferEvent> events)
	{
		queue.addAll(events);
		List<OfferEvent> snapshot = queue.snapshot();
		executor.execute(() -> store.saveQueue(snapshot));
	}

	/** Sends the next batch when one is due (every FLUSH_EVERY_MS on the executor). */
	private void flush()
	{
		if (!isLinked())
		{
			return;
		}
		long now = System.currentTimeMillis();
		List<OfferEvent> batch = queue.take(now);
		if (batch == null)
		{
			return;
		}
		int tzOffset = TimeZone.getDefault().getOffset(now) / 60_000;
		api.sendOffers(config.token(), tzOffset, batch, reply ->
		{
			if (reply.ok())
			{
				queue.sent(batch);
				lastSyncAt = System.currentTimeMillis();
				syncProblem = null;
				readStatus(accountsIn(reply.getBody()));
				List<OfferEvent> snapshot = queue.snapshot();
				store.saveQueue(snapshot);
			}
			else if (reply.getStatus() == 401)
			{
				// The site no longer knows this token (unlinked on the account page): stop sending until linked again.
				syncProblem = "Not linked any more: press Link";
				queue.failed(System.currentTimeMillis());
				configManager.unsetConfiguration(GameMarginsConfig.GROUP, GameMarginsConfig.TOKEN_KEY);
			}
			else if (reply.getStatus() == 400)
			{
				// Refused as malformed: it would never go through, and holds the rest up.
				log.debug("batch refused: {}", reply.getBody());
				queue.dropped(batch);
			}
			else
			{
				syncProblem = reply.getFailure() != null ? "gamemargins.com unreachable, retrying" : "gamemargins.com answered " + reply.getStatus() + ", retrying";
				queue.failed(System.currentTimeMillis());
			}
			refreshPanel();
		});
	}

	private void fetchLimits()
	{
		api.limits(reply ->
		{
			if (reply.ok() && reply.getBody() != null)
			{
				limits = api.readLimits(reply.getBody());
			}
		});
	}

	private void fetchStatus()
	{
		if (!isLinked())
		{
			return;
		}
		api.status(config.token(), reply ->
		{
			if (reply.ok() && reply.getBody() != null)
			{
				readStatus(accountsIn(reply.getBody()));
				refreshPanel();
			}
			else if (reply.getStatus() == 401)
			{
				syncProblem = "Not linked any more: press Link";
				configManager.unsetConfiguration(GameMarginsConfig.GROUP, GameMarginsConfig.TOKEN_KEY);
				refreshPanel();
			}
		});
	}

	private static JsonArray accountsIn(JsonObject body)
	{
		return body != null && body.has("accounts") && body.get("accounts").isJsonArray() ? body.getAsJsonArray("accounts") : null;
	}

	/** Today's profit per account, as the site works it out (the site pairs the trades; the plugin only sees offers). */
	private void readStatus(JsonArray accounts)
	{
		if (accounts == null)
		{
			return;
		}
		Map<String, Long> profit = new HashMap<>();
		Map<String, Integer> trades = new HashMap<>();
		for (JsonElement e : accounts)
		{
			if (!e.isJsonObject())
			{
				continue;
			}
			JsonObject a = e.getAsJsonObject();
			if (!a.has("hash") || !a.has("today"))
			{
				continue;
			}
			JsonObject today = a.getAsJsonObject("today");
			profit.put(a.get("hash").getAsString(), today.get("profit").getAsLong());
			trades.put(a.get("hash").getAsString(), today.get("trades").getAsInt());
		}
		synchronized (todayProfit)
		{
			todayProfit.putAll(profit);
			todayTrades.putAll(trades);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!GameMarginsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("siteUrl".equals(event.getKey()))
		{
			link.cancel();
			api = new ApiClient(http, gson, config.siteUrl());
			link = new LinkFlow(api, executor, this::linked, this::refreshPanel);
		}
		refreshPanel();
	}

	// --- what the overlay and the panel read -------------------------------------------------------

	public boolean isOverlayOn()
	{
		return config.overlay() && current != null && worldTracked;
	}

	/** The item's Grand Exchange buy limit per 4 hours, from the site's mapping; null when unknown. */
	public Integer limitOf(int itemId)
	{
		return limits.get(itemId);
	}

	/** The open buy-limit window of an item for the logged-in account, from this plugin's purchases; null when the limit is free. */
	public BuyLimits.Window windowFor(int itemId)
	{
		if (current == null)
		{
			return null;
		}
		Integer limit = limitOf(itemId);
		return BuyLimits.window(itemId, current.getPurchases(), System.currentTimeMillis(), limit == null ? -1 : limit);
	}

	private String nameOf(int itemId)
	{
		String name = itemNames.get(itemId);
		if (name == null)
		{
			// Only on the client thread; the panel's view is built there too.
			name = itemManager.getItemComposition(itemId).getName();
			itemNames.put(itemId, name);
		}
		return name;
	}

	private void saveCurrent()
	{
		if (current == null)
		{
			return;
		}
		// Serialised here, on the client thread, so the executor writes a snapshot and never races the tracker.
		OfferTracker tracker = current;
		Store.AccountFile file = new Store.AccountFile();
		file.setName(tracker.getName());
		file.setSlots(tracker.getSlots());
		file.setPurchases(new ArrayList<>(tracker.getPurchases()));
		String json = gson.toJson(file);
		String account = tracker.getAccount();
		executor.execute(() -> store.saveAccountJson(account, json));
	}

	/** Rebuilds the panel from the plugin's state; called from any thread, built on the client thread. */
	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			GameMarginsPanel.View v = new GameMarginsPanel.View();
			v.linked = isLinked();
			v.linkState = link.getState();
			v.userCode = link.getUserCode();
			v.linkProblem = link.getProblem();
			v.loggedIn = current != null && client.getGameState() == GameState.LOGGED_IN;
			v.worldTracked = worldTracked;
			v.lastSyncAt = lastSyncAt;
			v.queued = queue.size();
			v.syncProblem = syncProblem;
			if (current != null)
			{
				v.accountName = current.getName();
				v.slots = current.getSlots().clone();
				long now = System.currentTimeMillis();
				v.windows = BuyLimits.windows(current.getPurchases(), now, id -> limitOf(id));
				synchronized (todayProfit)
				{
					v.todayProfit = todayProfit.get(current.getAccount());
					v.todayTrades = todayTrades.get(current.getAccount());
				}
				Map<Integer, String> names = new HashMap<>();
				for (SlotState s : v.slots)
				{
					if (s != null && !s.isEmpty())
					{
						names.put(s.getItemId(), nameOf(s.getItemId()));
					}
				}
				for (BuyLimits.Window w : v.windows)
				{
					names.put(w.getItemId(), nameOf(w.getItemId()));
				}
				v.nameOf = id -> names.getOrDefault(id, "Item " + id);
			}
			panel.show(v);
		});
	}

	/** The toolbar icon: the brand's gold tile with a G, drawn here rather than shipped as a file. */
	private static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(new Color(242, 181, 68));
		g.fillRoundRect(0, 0, 16, 16, 5, 5);
		g.setColor(new Color(27, 20, 6));
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
		g.drawString("G", 4, 12);
		g.dispose();
		return image;
	}
}

package com.gamemargins;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.text.NumberFormat;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The buy limit in the Grand Exchange's offer setup screen (decision 3C): while a buy offer is being set up,
 * a small panel under the offer says how much of the item's limit is left and when it resets, from this
 * plugin's own purchases (BuyLimits) and the limits the site gave it. Drawn only on that screen, only for buys.
 */
public class GeOverlay extends Overlay
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.systemDefault());
	private static final Color ORANGE = new Color(220, 138, 0);
	private static final Color GREEN = new Color(55, 240, 70);

	private final Client client;
	private final GameMarginsPlugin plugin;
	private final PanelComponent panel = new PanelComponent();

	@Inject
	GeOverlay(Client client, GameMarginsPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isOverlayOn())
		{
			return null;
		}
		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (setup == null || setup.isHidden())
		{
			return null;
		}
		// 0 is a buy offer, 1 a sell; the item picked for it is in the search varp.
		if (client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE) != 0)
		{
			return null;
		}
		int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (itemId <= 0)
		{
			return null;
		}
		BuyLimits.Window window = plugin.windowFor(itemId);
		Integer limit = plugin.limitOf(itemId);
		panel.getChildren().clear();
		panel.getChildren().add(TitleComponent.builder().text("GameMargins").color(ORANGE).build());
		NumberFormat n = NumberFormat.getIntegerInstance();
		if (window == null)
		{
			panel.getChildren().add(LineComponent.builder()
				.left("Buy limit")
				.right(limit == null ? "unknown" : n.format(limit) + " free")
				.rightColor(GREEN)
				.build());
			panel.getChildren().add(LineComponent.builder().left("Nothing bought in the last 4 hours").build());
		}
		else
		{
			String left = window.getLeft() < 0 ? n.format(window.getUsed()) + " bought" : n.format(window.getLeft()) + " of " + n.format(window.getLimit()) + " left";
			panel.getChildren().add(LineComponent.builder()
				.left("Buy limit")
				.right(left)
				.rightColor(window.getLeft() == 0 ? Color.RED : Color.WHITE)
				.build());
			long remaining = window.getResets() - System.currentTimeMillis();
			panel.getChildren().add(LineComponent.builder()
				.left("Resets at " + CLOCK.format(Instant.ofEpochMilli(window.getResets())))
				.right("in " + BuyLimits.until(remaining))
				.build());
		}
		// Under the setup window, at its left edge.
		Rectangle bounds = setup.getBounds();
		if (bounds != null)
		{
			panel.setPreferredLocation(new Point(bounds.x, bounds.y + bounds.height + 4));
		}
		return panel.render(graphics);
	}
}

package com.gamemargins;

import com.google.gson.JsonObject;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;

/**
 * Linking the plugin to a gamemargins.com account (an OAuth-style device flow, the site's /link): ask the
 * site for a code, show the short one to the player and open the site's page with it, then poll with the
 * long one until the player has confirmed and the site hands over the token. Nothing of the player's
 * account ever goes through RuneLite: no password, no key to paste.
 */
@Slf4j
public class LinkFlow
{
	public enum State
	{
		IDLE, STARTING, WAITING, FAILED
	}

	private final ApiClient api;
	private final ScheduledExecutorService executor;
	private final Consumer<String> onToken;
	private final Runnable onChange;

	@Getter
	private volatile State state = State.IDLE;
	@Getter
	private volatile String userCode;
	@Getter
	private volatile String verifyUrl;
	@Getter
	private volatile String problem;
	private volatile String deviceCode;
	private volatile long expiresAt;
	private ScheduledFuture<?> poll;

	public LinkFlow(ApiClient api, ScheduledExecutorService executor, Consumer<String> onToken, Runnable onChange)
	{
		this.api = api;
		this.executor = executor;
		this.onToken = onToken;
		this.onChange = onChange;
	}

	/** Starts linking: asks the site for a code and opens the page to confirm it on. */
	public synchronized void start()
	{
		if (state == State.STARTING || state == State.WAITING)
		{
			return;
		}
		state = State.STARTING;
		problem = null;
		onChange.run();
		api.startLink(reply ->
		{
			if (!reply.ok() || reply.getBody() == null || !reply.getBody().has("deviceCode"))
			{
				fail(reply.getFailure() != null ? "Could not reach gamemargins.com" : "gamemargins.com refused (" + reply.getStatus() + ")");
				return;
			}
			JsonObject body = reply.getBody();
			deviceCode = body.get("deviceCode").getAsString();
			userCode = body.get("userCode").getAsString();
			verifyUrl = body.has("verifyUrl") ? body.get("verifyUrl").getAsString() : api.getSite() + "/link?code=" + userCode;
			int interval = body.has("interval") ? body.get("interval").getAsInt() : 5;
			int expiresIn = body.has("expiresIn") ? body.get("expiresIn").getAsInt() : 600;
			expiresAt = System.currentTimeMillis() + expiresIn * 1000L;
			state = State.WAITING;
			onChange.run();
			LinkBrowser.browse(verifyUrl);
			synchronized (this)
			{
				poll = executor.scheduleWithFixedDelay(this::pollOnce, interval, interval, TimeUnit.SECONDS);
			}
		});
	}

	/** Opens the site's page again (the player closed it). */
	public void openPage()
	{
		if (verifyUrl != null)
		{
			LinkBrowser.browse(verifyUrl);
		}
	}

	private void pollOnce()
	{
		if (state != State.WAITING)
		{
			return;
		}
		if (System.currentTimeMillis() > expiresAt)
		{
			fail("The code expired; press Link for a new one");
			return;
		}
		api.pollLink(deviceCode, reply ->
		{
			if (reply.getFailure() != null)
			{
				// The site is unreachable for the moment: keep polling until the code expires.
				return;
			}
			JsonObject body = reply.getBody();
			String status = body != null && body.has("status") ? body.get("status").getAsString() : "";
			if ("ok".equals(status) && body.has("token"))
			{
				stopPolling();
				state = State.IDLE;
				userCode = null;
				onChange.run();
				onToken.accept(body.get("token").getAsString());
			}
			else if ("expired".equals(status) || reply.getStatus() == 404 || reply.getStatus() == 410)
			{
				fail("The code expired; press Link for a new one");
			}
		});
	}

	private void fail(String why)
	{
		stopPolling();
		state = State.FAILED;
		problem = why;
		userCode = null;
		onChange.run();
	}

	public synchronized void cancel()
	{
		stopPolling();
		state = State.IDLE;
		userCode = null;
		problem = null;
	}

	private synchronized void stopPolling()
	{
		if (poll != null)
		{
			poll.cancel(false);
			poll = null;
		}
	}
}

package com.gamemargins;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One change of a Grand Exchange slot, as gamemargins.com receives it (POST /api/runelite/offers).
 * Field names are the JSON names; Gson serialises this class as is. Mirrors OfferEvent in the site's
 * core (packages/core/src/osrs/runelite.ts).
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class OfferEvent
{
	/** The game's account hash, as a decimal string: a Java long doesn't fit a JavaScript number. */
	private String account;
	/** The in-game name, when known. */
	private String name;
	/** 0 to 7. */
	private int slot;
	/** This plugin's own id for the offer: new when a slot goes from empty to buying or selling. */
	private String offerId;
	/** 0, 1, 2… per offer: the order of its events, so a resent batch changes nothing on the server. */
	private int seq;
	private int itemId;
	private boolean buy;
	/** EMPTY, BUYING, BOUGHT, CANCELLED_BUY, SELLING, SOLD or CANCELLED_SELL (RuneLite's GrandExchangeOfferState). */
	private String state;
	/** Asked for. */
	private int quantity;
	/** Filled so far. */
	private int filled;
	/** The offer's price per item. */
	private long price;
	/** Coins moved so far: spent on a buy, received (before tax) on a sell. */
	private long spent;
	/** When the slot changed, ms since the epoch. */
	private long at;
	/** The change was found at login: the fill happened some time while the plugin wasn't watching. */
	private boolean offline;
}

package com.gamemargins;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.function.Supplier;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Turns what the eight slots report into events for gamemargins.com, for one account. Pure: it holds the
 * slots' last known state, takes offer reads and a clock, and gives back the events to queue, so it can be
 * tested without a client.
 *
 * <p>The rules it knows:
 * <ul>
 *   <li>A slot that goes from empty to buying or selling starts a new offer with a fresh id; the same item,
 *   side, quantity and price with a filled count that follows on is the same offer; anything else in a
 *   non-empty slot is a new offer (the empty read in between was missed).</li>
 *   <li>Every read that changes the offer (state, filled, spent) is an event with the next sequence number;
 *   a read that changes nothing is dropped.</li>
 *   <li>A slot that reads empty while an offer was known is the offer's collection: an EMPTY event, then
 *   the slot is free.</li>
 *   <li>Logging in replays every slot, and a slot can read EMPTY before its real state arrives. The plugin
 *   calls {@link #beginReplay()} at login and drops the reads that follow; once the client has settled
 *   ({@link #endReplay} with the live slots) the tracker reconciles each slot against what it knew: an offer
 *   that finished or filled further while logged out is reported with {@code offline} set and the time of
 *   the reconciliation (it can only be late, never early, so a buy-limit timer never says "free" too soon),
 *   one that vanished is collected, one never seen before is started.</li>
 *   <li>Each increase of a buy's filled count is a {@link Purchase} at that moment, for the limit windows.</li>
 * </ul>
 */
public class OfferTracker
{
	public static final int SLOTS = 8;

	private final String account;
	private final Supplier<Long> clock;
	private final Supplier<String> ids;
	private final SlotState[] slots = new SlotState[SLOTS];
	private final List<Purchase> purchases = new ArrayList<>();
	private String name;
	private boolean replaying;
	/** Whether the persisted state has been read (or there was none): the login reconciliation waits for it. */
	private volatile boolean restored;

	public OfferTracker(String account, Supplier<Long> clock)
	{
		this(account, clock, () -> UUID.randomUUID().toString());
	}

	public OfferTracker(String account, Supplier<Long> clock, Supplier<String> ids)
	{
		this.account = account;
		this.clock = clock;
		this.ids = ids;
		for (int i = 0; i < SLOTS; i++)
		{
			slots[i] = new SlotState();
		}
	}

	public String getAccount()
	{
		return account;
	}

	public String getName()
	{
		return name;
	}

	public void setName(String name)
	{
		this.name = name;
	}

	public SlotState[] getSlots()
	{
		return slots;
	}

	/** The purchases of the last day (older ones are dropped as they age out). */
	public List<Purchase> getPurchases()
	{
		return purchases;
	}

	/** Restores the persisted state (Store); null for an account without one. */
	public void restore(SlotState[] saved, List<Purchase> savedPurchases)
	{
		if (saved != null)
		{
			for (int i = 0; i < SLOTS && i < saved.length; i++)
			{
				if (saved[i] != null)
				{
					slots[i] = saved[i];
				}
			}
		}
		purchases.clear();
		if (savedPurchases != null)
		{
			purchases.addAll(savedPurchases);
		}
		prunePurchases();
		restored = true;
	}

	public boolean isRestored()
	{
		return restored;
	}

	public boolean isReplaying()
	{
		return replaying;
	}

	/** Login (or a world hop) is about to replay the slots: the reads that follow are dropped until {@link #endReplay}. */
	public void beginReplay()
	{
		replaying = true;
	}

	/**
	 * The client has settled after login: compares every slot with what the plugin knew and emits what
	 * happened while it wasn't watching. {@code live} is the client's current offers, in slot order.
	 */
	public List<OfferEvent> endReplay(GrandExchangeOffer[] live)
	{
		replaying = false;
		List<OfferEvent> events = new ArrayList<>();
		if (live == null)
		{
			return events;
		}
		for (int i = 0; i < SLOTS && i < live.length; i++)
		{
			events.addAll(read(i, live[i], true));
		}
		return events;
	}

	/** A live change of a slot: the events to queue (none when nothing changed, or while replaying). */
	public List<OfferEvent> onChange(int slot, GrandExchangeOffer offer)
	{
		if (replaying || slot < 0 || slot >= SLOTS)
		{
			return new ArrayList<>();
		}
		return read(slot, offer, false);
	}

	private List<OfferEvent> read(int slot, GrandExchangeOffer offer, boolean offline)
	{
		List<OfferEvent> events = new ArrayList<>();
		if (offer == null)
		{
			return events;
		}
		SlotState known = slots[slot];
		long now = clock.get();
		if (offer.getState() == GrandExchangeOfferState.EMPTY)
		{
			if (!known.isEmpty())
			{
				// Collected (or gone while logged out): the offer's last event.
				known.setSeq(known.getSeq() + 1);
				known.setUpdatedAt(now);
				events.add(event(known, slot, "EMPTY", now, offline));
				slots[slot] = new SlotState();
			}
			return events;
		}
		if (!known.isEmpty() && !known.sameOffer(offer))
		{
			// Another offer sits there now: the known one was collected without us seeing the empty slot.
			known.setSeq(known.getSeq() + 1);
			known.setUpdatedAt(now);
			events.add(event(known, slot, "EMPTY", now, offline));
			slots[slot] = new SlotState();
			known = slots[slot];
		}
		boolean buy = SlotState.isBuyState(offer.getState());
		if (known.isEmpty())
		{
			SlotState fresh = new SlotState(ids.get(), 0, offer.getItemId(), buy, offer.getState().name(), offer.getTotalQuantity(), offer.getQuantitySold(), offer.getPrice(), offer.getSpent(), now, now);
			slots[slot] = fresh;
			if (buy && fresh.getFilled() > 0)
			{
				notePurchase(fresh.getItemId(), fresh.getFilled(), now);
			}
			events.add(event(fresh, slot, fresh.getState(), now, offline));
			return events;
		}
		boolean changed = !known.getState().equals(offer.getState().name()) || known.getFilled() != offer.getQuantitySold() || known.getSpent() != offer.getSpent();
		if (!changed)
		{
			return events;
		}
		int before = known.getFilled();
		known.setSeq(known.getSeq() + 1);
		known.setState(offer.getState().name());
		known.setFilled(Math.max(known.getFilled(), offer.getQuantitySold()));
		known.setSpent(Math.max(known.getSpent(), offer.getSpent()));
		known.setUpdatedAt(now);
		if (buy && known.getFilled() > before)
		{
			notePurchase(known.getItemId(), known.getFilled() - before, now);
		}
		events.add(event(known, slot, known.getState(), now, offline));
		return events;
	}

	private OfferEvent event(SlotState s, int slot, String state, long at, boolean offline)
	{
		return new OfferEvent(account, name, slot, s.getOfferId(), s.getSeq(), s.getItemId(), s.isBuy(), state, s.getQuantity(), s.getFilled(), s.getPrice(), s.getSpent(), at, offline);
	}

	private void notePurchase(int itemId, int quantity, long at)
	{
		purchases.add(new Purchase(itemId, quantity, at));
		prunePurchases();
	}

	/** Purchases older than a day can't be in any window that is still open (BuyLimits looks back that far). */
	private void prunePurchases()
	{
		long cutoff = clock.get() - BuyLimits.LOOKBACK_MS;
		purchases.removeIf(p -> p.getAt() < cutoff);
	}
}

package com.gamemargins;

import java.awt.Font;
import java.awt.FontFormatException;
import java.awt.RenderingHints;
import java.awt.font.TextAttribute;
import java.io.IOException;
import java.io.InputStream;
import java.util.Collections;
import javax.swing.JComponent;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.FontManager;

/**
 * The side panel's letters (the owner's choice, 12 October 2026): Geist, the letter of gamemargins.com, bundled in
 * {@code fonts/} under the SIL Open Font License ({@code fonts/OFL.txt}). RuneScape's pixel letters only come out even
 * at 100% and 200% display scaling; Geist stays sharp at any. Should a file fail to load, the whole panel keeps
 * RuneLite's own letters instead, so it never mixes the two.
 */
@Slf4j
final class PanelFonts
{
	/** Whether Geist loaded; when not, every role below is one of RuneLite's letters. */
	static final boolean GEIST;
	/** Names and values: the account, the slots, the buy limits. */
	static final Font BODY;
	/** Sentences, prices and status lines. */
	static final Font SMALL;
	/** The small capitals above a list ("OFFERS"). */
	static final Font SECTION;
	static final Font TITLE;
	static final Font BUTTON;
	/** The code to confirm on the site while linking. */
	static final Font CODE;

	static
	{
		Font regular = load("Geist-Regular.ttf");
		Font medium = load("Geist-Medium.ttf");
		Font semiBold = load("Geist-SemiBold.ttf");
		Font mono = load("GeistMono-Medium.ttf");
		GEIST = regular != null && medium != null && semiBold != null && mono != null;
		if (GEIST)
		{
			BODY = regular.deriveFont(13f);
			SMALL = regular.deriveFont(12f);
			SECTION = semiBold.deriveFont(11f).deriveFont(Collections.singletonMap(TextAttribute.TRACKING, 0.07f));
			TITLE = semiBold.deriveFont(16f);
			BUTTON = medium.deriveFont(13f);
			CODE = mono.deriveFont(24f);
		}
		else
		{
			BODY = FontManager.getRunescapeFont();
			SMALL = FontManager.getRunescapeSmallFont();
			SECTION = FontManager.getRunescapeSmallFont();
			TITLE = FontManager.getRunescapeBoldFont();
			BUTTON = FontManager.getRunescapeFont();
			CODE = FontManager.getRunescapeBoldFont().deriveFont(32f);
		}
	}

	private PanelFonts()
	{
	}

	/**
	 * Gives a component its letter. Geist is drawn smoothed; RuneLite's look and feel leaves smoothing to each font's
	 * own table, which keeps its pixel letters sharp.
	 */
	static <T extends JComponent> T use(T component, Font font)
	{
		component.setFont(font);
		if (GEIST)
		{
			component.putClientProperty(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		}
		return component;
	}

	private static Font load(String file)
	{
		try (InputStream in = PanelFonts.class.getResourceAsStream("fonts/" + file))
		{
			if (in == null)
			{
				log.warn("Font {} is missing from the plugin", file);
				return null;
			}
			return Font.createFont(Font.TRUETYPE_FONT, in);
		}
		catch (IOException | FontFormatException e)
		{
			log.warn("Could not load font {}", file, e);
			return null;
		}
	}
}

package com.gamemargins;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/** Items bought at a moment: what the buy-limit windows count (BuyLimits). Persisted with the account for a day. */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Purchase
{
	private int itemId;
	private int quantity;
	/** ms since the epoch. */
	private long at;
}

package com.gamemargins;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * What the plugin last knew of one slot: the offer sitting in it, with the id this plugin gave it and how
 * many events it has sent about it. Persisted per account (Store), so a login after a while can tell what
 * finished while the plugin wasn't watching. A slot with no offer has {@code offerId == null}.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class SlotState
{
	private String offerId;
	private int seq;
	private int itemId;
	private boolean buy;
	private String state;
	private int quantity;
	private int filled;
	private long price;
	private long spent;
	/** When this plugin first saw the offer (ms). */
	private long startedAt;
	/** When the slot last changed (ms). */
	private long updatedAt;

	public boolean isEmpty()
	{
		return offerId == null;
	}

	/** Whether a read of this state's side is a buy. */
	public static boolean isBuyState(GrandExchangeOfferState state)
	{
		return state == GrandExchangeOfferState.BUYING || state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.CANCELLED_BUY;
	}

	/** The same offer, as far as a slot can tell: item, side, quantity and price, and a filled count that follows on. */
	public boolean sameOffer(GrandExchangeOffer offer)
	{
		if (isEmpty() || offer.getState() == GrandExchangeOfferState.EMPTY)
		{
			return false;
		}
		return offer.getItemId() == itemId
			&& isBuyState(offer.getState()) == buy
			&& offer.getTotalQuantity() == quantity
			&& offer.getPrice() == price
			&& offer.getQuantitySold() >= filled;
	}

	/** Whether the Grand Exchange is done with the offer: bought, sold or cancelled. */
	public boolean isFinished()
	{
		return "BOUGHT".equals(state) || "SOLD".equals(state) || "CANCELLED_BUY".equals(state) || "CANCELLED_SELL".equals(state);
	}

	public boolean isCancelled()
	{
		return "CANCELLED_BUY".equals(state) || "CANCELLED_SELL".equals(state);
	}
}

package com.gamemargins;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * What the plugin keeps on disk, in RuneLite's folder for this plugin (Filepath, so the Plugin Hub's rules
 * are met): per account the slots as last known and the purchases of the last day ("account-<hash>.json"),
 * and the queue of events not yet delivered to gamemargins.com ("queue.json"). Written as JSON through
 * the injected Gson; a file that can't be read is treated as absent, never as a reason to stop.
 */
@Slf4j
public class Store
{
	private static final Type EVENTS = new TypeToken<List<OfferEvent>>()
	{
	}.getType();

	/** The persisted form of one account. */
	@Data
	@NoArgsConstructor
	public static class AccountFile
	{
		private String name;
		private SlotState[] slots;
		private List<Purchase> purchases;
	}

	private final Gson gson;
	private final Filepath dir;

	public Store(Gson gson, Filepath dir)
	{
		this.gson = gson;
		this.dir = dir;
	}

	private Filepath accountFile(String account)
	{
		// Account hashes may be negative: the file name keeps the digits only.
		return dir.join("account-" + account.replace("-", "n") + ".json");
	}

	public AccountFile loadAccount(String account)
	{
		return read(accountFile(account), AccountFile.class);
	}

	/** Writes an account's file from JSON the plugin made on the client thread (a snapshot, so no race with the tracker). */
	public void saveAccountJson(String account, String json)
	{
		writeText(accountFile(account), json);
	}

	public List<OfferEvent> loadQueue()
	{
		List<OfferEvent> events = read(dir.join("queue.json"), EVENTS);
		return events == null ? new ArrayList<>() : events;
	}

	public void saveQueue(List<OfferEvent> events)
	{
		write(dir.join("queue.json"), events);
	}

	private <T> T read(Filepath file, Type type)
	{
		try
		{
			if (!file.exists())
			{
				return null;
			}
			try (Reader reader = file.openBufferedReader())
			{
				return gson.fromJson(reader, type);
			}
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.debug("could not read {}", file, e);
			return null;
		}
	}

	private void write(Filepath file, Object value)
	{
		writeText(file, gson.toJson(value));
	}

	private void writeText(Filepath file, String json)
	{
		try
		{
			dir.createDirectories();
			// Written whole to a temporary file first, so a crash mid-write never leaves a half file behind.
			Filepath tmp = dir.join(file.getFileName() + ".tmp");
			try (Writer writer = tmp.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE))
			{
				writer.write(json);
			}
			tmp.moveTo(file, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			log.debug("could not write {}", file, e);
		}
	}
}

package com.gamemargins;

import java.util.Collection;
import java.util.EnumSet;
import net.runelite.api.WorldType;

/**
 * Worlds whose Grand Exchange is its own economy: offers there say nothing about the main game's buy limits
 * or prices, so the plugin ignores them (Leagues and other seasonals, Deadman, tournament and beta worlds,
 * fresh start worlds, the PvP Arena, speedrunning and no-save worlds).
 */
public final class WorldFilter
{
	private static final EnumSet<WorldType> OWN_ECONOMY = EnumSet.of(
		WorldType.SEASONAL,
		WorldType.DEADMAN,
		WorldType.TOURNAMENT_WORLD,
		WorldType.BETA_WORLD,
		WorldType.FRESH_START_WORLD,
		WorldType.PVP_ARENA,
		WorldType.QUEST_SPEEDRUNNING,
		WorldType.NOSAVE_MODE
	);

	private WorldFilter()
	{
	}

	/** Whether offers on a world of these types belong to the main game's economy. */
	public static boolean tracked(Collection<WorldType> types)
	{
		if (types == null)
		{
			return true;
		}
		for (WorldType t : types)
		{
			if (OWN_ECONOMY.contains(t))
			{
				return false;
			}
		}
		return true;
	}
}

package com.gamemargins;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class BuyLimitsTest
{
	private static final long H = 3_600_000;
	private static final long T = 1_791_700_000_000L;

	@Test
	public void theWindowStartsAtTheFirstPurchaseAndEndsFourHoursLaterWhateverCameAfter()
	{
		List<Purchase> buys = Arrays.asList(new Purchase(4151, 100, T), new Purchase(4151, 50, T + H + H / 2));
		BuyLimits.Window w = BuyLimits.window(4151, buys, T + 2 * H, 500);
		assertEquals(T, w.getStart());
		assertEquals(T + 4 * H, w.getResets());
		assertEquals(150, w.getUsed());
		assertEquals(350, w.getLeft());
		assertNull(BuyLimits.window(4151, buys, T + 4 * H, 500));
	}

	@Test
	public void aPurchaseAfterTheWindowStartsANewOne()
	{
		List<Purchase> buys = Arrays.asList(new Purchase(4151, 10, T - 4 * H), new Purchase(4151, 20, T - H), new Purchase(4151, 30, T + H));
		BuyLimits.Window w = BuyLimits.window(4151, buys, T + 2 * H, 100);
		assertEquals(T + H, w.getStart());
		assertEquals(30, w.getUsed());
		assertEquals(70, w.getLeft());
		// A purchase timed in the future counts as now; an unknown limit shows -1 left.
		List<Purchase> ahead = new ArrayList<>(buys);
		ahead.add(new Purchase(4151, 5, T + 10 * H));
		assertEquals(35, BuyLimits.window(4151, ahead, T + 2 * H, 100).getUsed());
		assertEquals(-1, BuyLimits.window(4151, buys, T + 2 * H, -1).getLeft());
		assertEquals(0, BuyLimits.window(4151, Arrays.asList(new Purchase(4151, 600, T)), T + 1, 500).getLeft());
	}

	@Test
	public void manyItemsAtOnceSoonestResetFirst()
	{
		List<Purchase> buys = Arrays.asList(new Purchase(4151, 3, T + H), new Purchase(560, 1000, T), new Purchase(4151, 2, T + 2 * H), new Purchase(995, 1, T - 5 * H));
		// Boxed on purpose: a conditional mixing int literals with null unboxes the null and throws.
		List<BuyLimits.Window> windows = BuyLimits.windows(buys, T + 2 * H, id -> id == 4151 ? Integer.valueOf(70) : id == 560 ? Integer.valueOf(25_000) : null);
		assertEquals(2, windows.size());
		assertEquals(560, windows.get(0).getItemId());
		assertEquals(4151, windows.get(1).getItemId());
		assertEquals(5, windows.get(1).getUsed());
		assertEquals(65, windows.get(1).getLeft());
	}

	@Test
	public void timeLeftInWords()
	{
		assertEquals("under a minute", BuyLimits.until(30_000));
		assertEquals("45 min", BuyLimits.until(45 * 60_000));
		assertEquals("2h 05m", BuyLimits.until(2 * H + 5 * 60_000));
	}
}

package com.gamemargins;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class EventQueueTest
{
	private static OfferEvent event(int seq)
	{
		return new OfferEvent("1", null, 0, "offer", seq, 4151, true, "BUYING", 1, 0, 1, 0, 1_791_700_000_000L + seq, false);
	}

	private static List<OfferEvent> events(int n, int from)
	{
		List<OfferEvent> out = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			out.add(event(from + i));
		}
		return out;
	}

	@Test
	public void batchesGoOutInOrderOneAtATimeAndAreDroppedOnceSent()
	{
		EventQueue q = new EventQueue();
		q.addAll(events(450, 0));
		List<OfferEvent> first = q.take(0);
		assertNotNull(first);
		assertEquals(EventQueue.BATCH, first.size());
		assertEquals(0, first.get(0).getSeq());
		assertNull("one in flight at a time", q.take(0));
		q.sent(first);
		assertEquals(250, q.size());
		List<OfferEvent> second = q.take(0);
		assertEquals(200, second.get(0).getSeq());
		q.sent(second);
		assertEquals(50, q.take(0).size());
	}

	@Test
	public void aFailureKeepsTheBatchAndBacksOffDoublingUpToFiveMinutes()
	{
		EventQueue q = new EventQueue();
		q.addAll(events(3, 0));
		List<OfferEvent> batch = q.take(0);
		q.failed(1_000);
		assertEquals(3, q.size());
		assertEquals(EventQueue.FIRST_BACKOFF_MS, q.getBackoffMs());
		assertNull("not before the backoff", q.take(1_000 + EventQueue.FIRST_BACKOFF_MS - 1));
		assertNotNull(q.take(1_000 + EventQueue.FIRST_BACKOFF_MS));
		q.failed(10_000);
		assertEquals(2 * EventQueue.FIRST_BACKOFF_MS, q.getBackoffMs());
		for (int i = 0; i < 10; i++)
		{
			q.take(1_000_000L * (i + 1));
			q.failed(1_000_000L * (i + 1));
		}
		assertEquals(EventQueue.MAX_BACKOFF_MS, q.getBackoffMs());
		q.take(100_000_000L);
		q.sent(batch);
		assertEquals(0, q.getBackoffMs());
		assertEquals(0, q.size());
	}

	@Test
	public void theQueueIsBoundedAndKeepsTheNewest()
	{
		EventQueue q = new EventQueue();
		q.addAll(events(EventQueue.MAX + 10, 0));
		assertEquals(EventQueue.MAX, q.size());
		assertEquals(10, q.snapshot().get(0).getSeq());
	}

	@Test
	public void theLastSessionsEventsGoInFrontOfNewOnes()
	{
		EventQueue q = new EventQueue();
		q.addAll(events(2, 100));
		q.restore(events(3, 0));
		assertEquals(5, q.size());
		assertEquals(0, q.snapshot().get(0).getSeq());
		assertEquals(100, q.snapshot().get(3).getSeq());
		q.clear();
		assertEquals(0, q.size());
	}
}

package com.gamemargins;

import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/** A slot as the client would report it, for the tests. */
class FakeOffer implements GrandExchangeOffer
{
	private final int itemId;
	private final GrandExchangeOfferState state;
	private final int total;
	private final int sold;
	private final long price;
	private final long spent;

	FakeOffer(int itemId, GrandExchangeOfferState state, int total, int sold, long price, long spent)
	{
		this.itemId = itemId;
		this.state = state;
		this.total = total;
		this.sold = sold;
		this.price = price;
		this.spent = spent;
	}

	static FakeOffer empty()
	{
		return new FakeOffer(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0);
	}

	@Override
	public int getQuantitySold()
	{
		return sold;
	}

	@Override
	public int getItemId()
	{
		return itemId;
	}

	@Override
	public int getTotalQuantity()
	{
		return total;
	}

	@Override
	public long getPrice()
	{
		return price;
	}

	@Override
	public long getSpent()
	{
		return spent;
	}

	@Override
	public GrandExchangeOfferState getState()
	{
		return state;
	}
}

